/bin/zsh -lc "sandbox_url='http://127.0.0.1:61496'
for scenario in happy rate-limit transient-503 permanent-429 bad-request; do
  curl -sS -o /dev/null -w \"%{http_code}\\n\" -X POST \""'$sandbox_url/control/reset" -H '"'content-type: application/json' --data \"{\\\"scenario\\\":\\\""'$scenario'"\\\"}\"
  SCENARIO=\""'$scenario" node --input-type=module <<'"'EOF'
import { fetchAllTickets } from './src/client.mjs';
const delays = [];
try {
  const tickets = await fetchAllTickets({
    baseUrl: 'http://127.0.0.1:61496',
    sleep: async (milliseconds) => delays.push(milliseconds),
  });
  console.log(JSON.stringify({ scenario: process.env.SCENARIO, ids: tickets.map(({ id }) => id), delays }));
} catch (error) {
  console.log(JSON.stringify({ scenario: process.env.SCENARIO, error: error.message, delays }));
}
EOF
  curl -sS \""'$sandbox_url/control/stats"
done'

